def gf8_add(a, b):
    return a ^ b

def gf8_mul(a, b):
    result = 0
    while b:
        if b & 1:
            result ^= a
        a <<= 1
        if a & 8:
            a ^= 0b1011
        b >>= 1
    return result

n = 8

# Construction using GF(8):
# X[i][j] = i + alpha * j  (in GF(8))
# Y[i][j] = i + beta * j   (in GF(8))
# where alpha != beta, alpha != 0, beta != 0, alpha != beta
# These are orthogonal Latin squares!

# Let's try alpha=1, beta=2
alpha = 1
beta = 2

X = [[gf8_add(i, gf8_mul(alpha, j)) for j in range(n)] for i in range(n)]
Y = [[gf8_add(i, gf8_mul(beta, j)) for j in range(n)] for i in range(n)]

print("X is Latin:", check_latin(X))
print("Y is Latin:", check_latin(Y))
print("Orthogonal:", check_orthogonal(X, Y))

